bool StructTraits<::skus::mojom::SkusResult::DataView, ::skus::mojom::SkusResultPtr>::Read(
    ::skus::mojom::SkusResult::DataView input,
    ::skus::mojom::SkusResultPtr* output) {
  bool success = true;
  ::skus::mojom::SkusResultPtr result(::skus::mojom::SkusResult::New());
  
      if (success && !input.ReadCode(&result->code))
        success = false;
      if (success && !input.ReadMessage(&result->message))
        success = false;
  *output = std::move(result);
  return success;
}

