SkusServiceAsyncWaiter::SkusServiceAsyncWaiter(
    SkusService* proxy) : proxy_(proxy) {}

SkusServiceAsyncWaiter::~SkusServiceAsyncWaiter() = default;


void SkusServiceAsyncWaiter::RefreshOrder(
    const std::string& domain, const std::string& order_id, SkusResultPtr* out_response) {
  base::RunLoop loop;
  proxy_->RefreshOrder(
      std::move(domain),
      std::move(order_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             SkusResultPtr* out_response
,
             SkusResultPtr response) {*out_response = std::move(response);
            loop->Quit();
          },
          &loop,
          out_response));
  loop.Run();
}

SkusResultPtr SkusServiceAsyncWaiter::RefreshOrder(
    const std::string& domain, const std::string& order_id) {
  SkusResultPtr async_wait_result;
  RefreshOrder(std::move(domain),std::move(order_id),&async_wait_result);
  return async_wait_result;
}

